/**
 * Maps each blog article slug to its cover image and the alt text
 * consumed by <Image alt={…}>.
 *
 * Two kinds of entries live here:
 *  - editorial SVG covers under /images/blog/covers/, generated by
 *    `scripts/generate-blog-covers.ts` (`npx tsx scripts/generate-blog-covers.ts`
 *    after changing titles / subtitles / categories in that script);
 *  - photo covers under /images/blog/<slug>.webp (1200×630), MAINTAINED BY
 *    HAND — the generator knows nothing about them. Re-running it rewrites
 *    this file with the SVG entries only: merge the photo entries back
 *    before committing.
 */

export interface BlogCover {
  cover: string;
  alt: string;
}

